-- Phase A6 (Global site controls) tables, generated by drizzle-kit from src/server/db/schema-site.ts and reviewed: table
-- options added to every CREATE TABLE (InnoDB, utf8mb4, utf8mb4_unicode_520_ci), ASCII key columns checked. A1-DATABASE-
-- SCHEMA §7 "Navigation, site settings, theme, interface text and redirects" is the authority for every table and column:
-- site_settings (+ translations, company_phones, ui_strings + translations), the company, contact and SEO defaults with
-- the interface text; menus (+ menu_items, menu_item_translations), the design's four menu slots; theme_settings (+
-- design_token_overrides), the controlled design-token overrides; redirects. Beyond A1 (A6 report, item 3):
-- menu_items.link_type 'route' with route_key (a site page by its route key), redirects.lock_version, an ASCII
-- redirects.target_path, and checks for what the application validates too (singleton ids, positions, E.164, maximum
-- lengths, a redirect's source address, status code and target columns). No existing table changes and no row is
-- written here (the slots, singletons and interface-text keys are 0007). Never edited after it has been applied anywhere.
CREATE TABLE `company_phones` (
	`id` char(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
