	`position` int unsigned NOT NULL,
	`display` varchar(32) NOT NULL,
	`e164` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`has_whatsapp` boolean NOT NULL,
	`is_visible` boolean NOT NULL DEFAULT true,
	CONSTRAINT `company_phones_id` PRIMARY KEY(`id`),
	CONSTRAINT `uq_company_phones_position` UNIQUE(`settings_id`,`position`),
	CONSTRAINT `ck_company_phones_position` CHECK(`company_phones`.`position` >= 1),
	CONSTRAINT `ck_company_phones_e164` CHECK(`company_phones`.`e164` REGEXP '^\\+[1-9][0-9]{6,14}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
