	`project_id` char(26) CHARACTER SET ascii COLLATE ascii_bin,
	`collection` varchar(32) CHARACTER SET ascii COLLATE ascii_bin,
	`anchor` varchar(64) CHARACTER SET ascii COLLATE ascii_bin,
	`url` varchar(500),
	`open_in_new_tab` boolean NOT NULL DEFAULT false,
	`is_visible` boolean NOT NULL DEFAULT true,
	`show_desktop` boolean NOT NULL DEFAULT true,
